Future<int> countInIsolate(String text) async {
  final answer = ReceivePort();
  await Isolate.spawn(_worker, [answer.sendPort, text]);
  final result = await answer.first as int;
  answer.close();
  return result;
}

// top-level: the child doesn't inherit the parent's state
void _worker(List<Object> message) {
  final send = message[0] as SendPort;
  final text = message[1] as String;
  send.send(text.split(' ').length);
}

